function NESTED_SLOPE_CERTIFICATE(N1, N2, D):
    require N1 > 0 and N2 > 0
    require N2 mod N1 = 0        // the windows must be nested
    c <- N2 / N1
    d <- |D|

    // nested bound: |D| <= L / N1   (no N2 dependence)
    certified <- N1 * d

    // generic bound: |D| <= 2L(1/N1 + 1/N2)
    generic   <- d / (2 * (1/N1 + 1/N2))

    return (certified_slope_floor = certified,
            generic_slope_floor   = generic,
            sharpening            = certified / generic,
            tightness             = (N2 - N1) / N2)   // 3/4 at (240,960)

function INTRINSIC(d_coarse, d_fine, c):
    return (c * d_fine - d_coarse) / (c - 1)

function RICHARDSON_ANALYSE(d1, d2, d1_lo, d1_hi, d2_lo, d2_hi, c, f):
    require c >= 2
    I          <- INTRINSIC(d1, d2, c)
    resolution <- d1 - I                      // = (c/(c-1)) * (d1 - d2)
    recovery   <- (d1 - d2) / d1              // the reported ratio
    inflation  <- c / (c - 1)                 // 4/3 at c = 4

    // exact interval propagation: opposite corners of the box
    share_lo <- INTRINSIC(d1_hi, d2_lo, c) / d1_hi
    share_hi <- INTRINSIC(d1_lo, d2_hi, c) / d1_lo

    // third nested cell at N3 = f * N1 is fully determined
    function THIRD(a, b):
        i <- INTRINSIC(a, b, c)
        return i + (a - i) / f

    return (intrinsic_level        = I,
            resolution_share       = resolution / d1,
            between_cell_recovery  = recovery,
            inflation_factor       = inflation,
            intrinsic_share_range  = [share_lo, share_hi],
            third_cell             = THIRD(d1, d2),
            third_cell_range       = [THIRD(d1_hi, d2_lo),
                                      THIRD(d1_lo, d2_hi)])

function TRIAGE(N_coarse, N_fine, D_lower, coarse_drop,
                share_interval, tolerance = 2):
    // upper bound on ambiguity  ->  certified slope
    L <- N_coarse * D_lower

    // lower bound on ambiguity  ->  the design's blind spot
    structural       <- L / (4 * N_fine)
    structural_share <- structural / coarse_drop

    statistical <- share_interval.high - share_interval.low
    ratio       <- statistical / structural_share

    if ratio >= tolerance:
        return ('more seeds',
                'the ladder can separate the hypotheses; the interval is
                 wide because of sampling noise')
    else if ratio <= 1 / tolerance:
        return ('finer windows',
                'replication cannot help: two admissible responses agree
                 on every cell of this ladder')
    else:
        return ('both', 'the two sources are comparable')
